(* [comment removed for export] *)
Definition dd_cov (E : env) (s : ddseen) (x : word) : Prop :=
  exists a w, dd_has s a w = true
              /\ bv_unsigned (adenot E a) <= bv_unsigned x < bv_unsigned (adenot E a) + Z.of_nat w.

